from dataclasses import dataclass
import json


@dataclass(frozen=True)
class Product:
    id: str
    name: str
    price_inr: int
    in_stock: bool = True


class CatalogError(Exception):
    """Raised when one product in the catalog can't be used."""


def parse_product(raw: dict) -> Product:
    try:
        return Product(
            id=raw["id"],
            name=raw["name"],
            price_inr=int(raw["price_inr"]),
            in_stock=raw.get("in_stock", True),
        )
    except KeyError as missing:
        raise CatalogError(f"{raw.get('id')}: missing field {missing}") from None
    except (TypeError, ValueError):
        raise CatalogError(f"{raw.get('id')}: bad price {raw.get('price_inr')!r}") from None


def load_catalog(text: str) -> list[Product]:
    products: list[Product] = []
    for raw in json.loads(text):
        try:
            products.append(parse_product(raw))
        except CatalogError as err:
            print("skipped", err)
    return products


def cheapest_in_stock(products: list[Product]) -> Product | None:
    available = [p for p in products if p.in_stock]
    return min(available, key=lambda p: p.price_inr) if available else None


CATALOG = """[
  {"id": "p1", "name": "Toned milk 1L", "price_inr": 58},
  {"id": "p2", "name": "Brown bread", "price_inr": "45"},
  {"id": "p3", "name": "Paneer 200g", "price_inr": "eighty"},
  {"id": "p4", "price_inr": 30},
  {"id": "p5", "name": "Curd 400g", "price_inr": 35, "in_stock": false}
]"""

if __name__ == "__main__":
    products = load_catalog(CATALOG)
    print(f"loaded {len(products)} products")
    for p in products:
        stock = "in stock" if p.in_stock else "out"
        print(f"  {p.id}  {p.name:<14} ₹{p.price_inr:>3}  {stock}")
    best = cheapest_in_stock(products)
    print("cheapest in stock:", best.name if best else "none")

import asyncio
import time

import httpx

RETRYABLE = {429, 500, 502, 503, 504}
calls = {"n": 0}


def flaky_server(request: httpx.Request) -> httpx.Response:
    """Stands in for a real API: fails twice, then answers."""
    calls["n"] += 1
    if request.url.path == "/products/p404":
        return httpx.Response(404, json={"error": "not found"})
    if calls["n"] < 3:
        return httpx.Response(503, json={"error": "busy"})
    pid = request.url.path.split("/")[-1]
    return httpx.Response(200, json={"id": pid, "price_inr": 58})


def get_with_retry(client: httpx.Client, path: str, tries: int = 4, base_delay: float = 0.2) -> dict:
    for attempt in range(1, tries + 1):
        try:
            resp = client.get(path)
        except httpx.TimeoutException:
            print(f"attempt {attempt}: timeout")
        else:
            print(f"attempt {attempt}: HTTP {resp.status_code}")
            if resp.status_code not in RETRYABLE:
                resp.raise_for_status()          # 4xx: our fault, retrying won't help
                return resp.json()
        if attempt < tries:
            time.sleep(base_delay * 2 ** (attempt - 1))   # 0.2s, 0.4s, 0.8s
    raise RuntimeError(f"gave up after {tries} attempts")


async def fetch_many(ids: list[str]) -> list[dict]:
    async with httpx.AsyncClient(transport=httpx.MockTransport(flaky_server),
                                 base_url="https://api.example.test", timeout=2.0) as client:
        responses = await asyncio.gather(*(client.get(f"/products/{i}") for i in ids))
    return [r.json() for r in responses]


if __name__ == "__main__":
    with httpx.Client(transport=httpx.MockTransport(flaky_server),
                      base_url="https://api.example.test", timeout=2.0) as client:
        print(get_with_retry(client, "/products/p1"))
        print(asyncio.run(fetch_many(["p2", "p3"])))
        try:
            get_with_retry(client, "/products/p404")
        except httpx.HTTPStatusError as err:
            print("not retried:", err.response.status_code)

