import json
from typing import Literal

from pydantic import BaseModel, Field, ValidationError


class Item(BaseModel):
    name: str
    qty: float = Field(gt=0)
    unit: Literal["g", "kg", "ml", "l", "pcs"]


class ShoppingPlan(BaseModel):
    people: int = Field(ge=1, le=20)
    diet: Literal["veg", "non-veg", "vegan", "jain", "any"]
    budget_inr: int | None = None
    items: list[Item] = Field(min_length=1)


class NeedsClarification(BaseModel):
    question: str


SYSTEM = ("Convert the grocery request into JSON matching this schema: "
          + json.dumps(ShoppingPlan.model_json_schema())
          + ' If the request is too vague, reply {"question": "..."} instead. JSON only.')


class FakeModel:
    """Stands in for a real LLM so this runs offline. Replies are scripted per request."""
    SCRIPT = {
        "dinner for 4, veg, under 800": [
            '{"people": 4, "diet": "veg", "budget_inr": 800, "items": [{"name": "paneer", "qty": 400, "unit": "grams"}]}',
            '{"people": 4, "diet": "veg", "budget_inr": 800, "items": [{"name": "paneer", "qty": 400, "unit": "g"}, {"name": "rice", "qty": 1, "unit": "kg"}]}',
        ],
        "stuff for the party": ['{"question": "How many people, and any dietary needs?"}'],
    }

    def __init__(self):
        self.calls = 0

    def complete(self, system: str, user: str, attempt: int) -> str:
        self.calls += 1
        replies = self.SCRIPT[user.split("\n")[0]]
        return replies[min(attempt, len(replies) - 1)]


def plan_from_request(model: FakeModel, text: str, max_attempts: int = 2):
    feedback = ""
    for attempt in range(max_attempts):
        raw = model.complete(SYSTEM, text + feedback, attempt)
        data = json.loads(raw)
        if "question" in data:
            return NeedsClarification(**data)
        try:
            return ShoppingPlan.model_validate(data)
        except ValidationError as err:
            first = err.errors()[0]
            print(f"  attempt {attempt + 1} invalid: {'.'.join(map(str, first['loc']))}: {first['msg']}")
            feedback = f"\nYour last reply was invalid: {first['msg']}. Fix it."
    raise ValueError("model did not produce a valid plan")


model = FakeModel()
for request in ["dinner for 4, veg, under 800", "stuff for the party"]:
    print(f"request: {request!r}")
    result = plan_from_request(model, request)
    print(" ", type(result).__name__, result.model_dump())
print("model calls:", model.calls)

import hashlib
import time


def estimate_tokens(text: str) -> int:
    """Rough rule of thumb (~4 characters per token for English). Use the provider's counter for billing."""
    return max(1, len(text) // 4)


def fit_history(messages: list[str], budget: int) -> list[str]:
    """Keep the newest messages that fit the token budget."""
    kept, used = [], 0
    for msg in reversed(messages):
        cost = estimate_tokens(msg)
        if used + cost > budget:
            break
        kept.append(msg)
        used += cost
    return list(reversed(kept))


class TTLCache:
    def __init__(self, ttl_s: float, clock=time.monotonic):
        self.ttl, self.clock, self.store = ttl_s, clock, {}

    def get_or_call(self, prompt: str, call):
        key = hashlib.sha256(prompt.encode()).hexdigest()
        hit = self.store.get(key)
        if hit and self.clock() - hit[1] < self.ttl:
            return hit[0], "hit"
        value = call(prompt)
        self.store[key] = (value, self.clock())
        return value, "miss"


def fake_stream(text: str):
    """A real SDK yields chunks like this as the model generates them."""
    for word in text.split():
        yield word + " "


history = ["user: I am vegetarian"] + [f"user: filler message number {i} about snacks" for i in range(30)] + ["user: plan lunch for 2"]
