import math

PRODUCTS = {
    "p1": "Amul toned milk 1L", "p2": "Nandini dahi 400g", "p3": "Brown bread",
    "p4": "Poha thick 500g", "p5": "Roasted makhana", "p6": "Vim dishwash gel",
    "p7": "Scotch-Brite scrub pad", "p8": "Greek yogurt plain", "p9": "Cornflakes",
}

# A TOY embedding model: each word maps to hand-set meaning dimensions
# [dairy, breakfast, snack, cleaning, healthy]. Real models learn ~1000 dims from data.
WORD_VEC = {
    "milk": [1, .6, 0, 0, .3], "dahi": [1, .3, .2, 0, .6], "curd": [1, .3, .2, 0, .6],
    "yogurt": [1, .3, .3, 0, .7], "bread": [0, 1, .2, 0, .1], "poha": [0, 1, .1, 0, .4],
    "cornflakes": [0, 1, .1, 0, .2], "breakfast": [.2, 1, 0, 0, 0], "makhana": [0, 0, 1, 0, .8],
    "snack": [0, 0, 1, 0, 0], "healthy": [0, 0, .2, 0, 1], "dishwash": [0, 0, 0, 1, 0],
    "scrub": [0, 0, 0, 1, 0], "cleaning": [0, 0, 0, 1, 0], "utensils": [0, 0, 0, .9, 0],
}


def words(text):
    return [w.strip(".,").lower() for w in text.replace("-", " ").split()]


def embed(text):
    vecs = [WORD_VEC[w] for w in words(text) if w in WORD_VEC]
    return [sum(col) for col in zip(*vecs)] if vecs else [0.0] * 5


def cosine(a, b):
    dot = sum(x * y for x, y in zip(a, b))
    na, nb = math.sqrt(sum(x * x for x in a)), math.sqrt(sum(y * y for y in b))
    return dot / (na * nb) if na and nb else 0.0


def keyword_score(query, doc):
    q = set(words(query))
    return len(q & set(words(doc))) / len(q)


def search(query, mode, k=3):
    q_vec = embed(query)
    scored = []
    for pid, name in PRODUCTS.items():
        kw, sem = keyword_score(query, name), cosine(q_vec, embed(name))
        score = {"keyword": kw, "semantic": sem, "hybrid": 0.4 * kw + 0.6 * sem}[mode]
        scored.append((score, pid))
    return [pid for score, pid in sorted(scored, reverse=True)[:k] if score > 0]


# labelled test queries: which products a person would accept
TESTS = {"curd": {"p2", "p8"}, "something for breakfast": {"p3", "p4", "p9"},
         "healthy snack": {"p5"}, "cleaning utensils": {"p6", "p7"}, "Amul milk": {"p1"}}

for mode in ["keyword", "semantic", "hybrid"]:
    recalls = [len(set(search(q, mode)) & want) / len(want) for q, want in TESTS.items()]
    print(f"{mode:<9} recall@3 = {sum(recalls) / len(recalls):.2f}   'curd' -> {search('curd', mode)}")

