# Policy for the backend's IAM role: call one approved model, in one region, nothing else.
GOOD = {
    "Version": "2012-10-17",
    "Statement": [{
        "Sid": "InvokeApprovedModel",
        "Effect": "Allow",
        "Action": ["bedrock:InvokeModel", "bedrock:InvokeModelWithResponseStream"],
        "Resource": "arn:aws:bedrock:us-east-1::foundation-model/EXAMPLE-MODEL-ID",
    }],
}
TOO_BROAD = {
    "Version": "2012-10-17",
    "Statement": [{"Effect": "Allow", "Action": "bedrock:*", "Resource": "*"},
                  {"Effect": "Allow", "Action": "s3:*", "Resource": "*"}],
}


def lint(policy: dict) -> list[str]:
    problems = []
    for i, st in enumerate(policy["Statement"]):
        actions = st["Action"] if isinstance(st["Action"], list) else [st["Action"]]
        resources = st["Resource"] if isinstance(st["Resource"], list) else [st["Resource"]]
        if st["Effect"] != "Allow":
            continue
        for a in actions:
            if a == "*" or a.endswith(":*"):
                problems.append(f"statement {i}: wildcard action {a!r}")
        if "*" in resources:
            problems.append(f"statement {i}: applies to every resource")
    return problems


for name, policy in [("good", GOOD), ("too broad", TOO_BROAD)]:
    found = lint(policy)
    print(f"{name}: {'OK' if not found else str(len(found)) + ' problem(s)'}")
    for p in found:
        print("  -", p)
