import json

ORDERS = {"A1029": {"user_id": "u_42", "status": "packing", "eta_min": 25},
          "B7777": {"user_id": "u_88", "status": "delivered", "eta_min": 0}}
CANCELLED_KEYS: set[str] = set()

TOOLS = [  # what the model is told about each tool (JSON schema)
    {"name": "get_order_status", "description": "Status and ETA of one of the user's orders",
     "input_schema": {"type": "object", "properties": {"order_id": {"type": "string"}}, "required": ["order_id"]}},
    {"name": "cancel_order", "description": "Cancel an order. Needs user confirmation.",
     "input_schema": {"type": "object", "properties": {"order_id": {"type": "string"}}, "required": ["order_id"]}},
]


class NotAllowed(Exception):
    pass


def get_order_status(user_id, order_id):
    order = ORDERS.get(order_id)
    if not order or order["user_id"] != user_id:          # authorization lives HERE, not in the prompt
        raise NotAllowed("order not found for this user")
    return {"status": order["status"], "eta_min": order["eta_min"]}


def cancel_order(user_id, order_id, confirmed, idempotency_key):
    order = ORDERS.get(order_id)
    if not order or order["user_id"] != user_id:
        raise NotAllowed("order not found for this user")
    if not confirmed:
        return {"needs_confirmation": True}
    if idempotency_key in CANCELLED_KEYS:                 # a retry must not cancel twice
        return {"status": "cancelled", "duplicate": True}
    if order["status"] not in ("placed", "packing"):
        return {"error": "too late to cancel"}
    order["status"] = "cancelled"
    CANCELLED_KEYS.add(idempotency_key)
    return {"status": "cancelled"}


def fake_model(messages):
    """Scripted stand-in for an LLM that supports tool calling."""
    last = messages[-1]
    if last["role"] == "tool":
        r = last["content"]
        if "error" in r:
            return {"text": f"Sorry, I couldn't do that: {r['error']}."}
        if r.get("needs_confirmation"):
            return {"text": "Do you want me to cancel it? Reply yes to confirm."}
        if r.get("status") == "cancelled":
            return {"text": "Your order is cancelled."}
        return {"text": f"Your order is {r['status']}, about {r['eta_min']} min away."}
    text = last["content"].lower()
    oid = next((w.strip("#?.") for w in text.split() if w.strip("#?.").upper() in ("A1029", "B7777")), None)
    if "cancel" in text and oid:
        return {"tool": "cancel_order", "args": {"order_id": oid.upper()}}
    if oid:
        return {"tool": "get_order_status", "args": {"order_id": oid.upper()}}
    return {"text": "Which order number do you mean?"}


def run_turn(user_id, text, confirmed=False, max_steps=3):
    messages = [{"role": "user", "content": text}]
    for step in range(max_steps):                         # stopping condition
        reply = fake_model(messages)
        if "text" in reply:
            return reply["text"]
        name, args = reply["tool"], reply["args"]
        print(f"   tool_call {name}({json.dumps(args)})")
        try:
            if name == "get_order_status":
                result = get_order_status(user_id, **args)
            else:
                result = cancel_order(user_id, **args, confirmed=confirmed,
                                      idempotency_key=f"cancel-{args['order_id']}")
        except NotAllowed as err:
            result = {"error": str(err)}
        print(f"   tool_result {json.dumps(result)}")
        messages.append({"role": "tool", "content": result})
    return "Stopped: too many steps."


for text, confirmed in [("Where is order #A1029?", False), ("Where is order #B7777?", False),
