import re

# A deterministic workflow: when the steps are known, code decides them, not a model.
ORDER_ID = re.compile(r"\b([A-Z]\d{4})\b")


def classify(text: str) -> str:
    t = text.lower()
    if "cancel" in t:
        return "cancel"
    if any(w in t for w in ("where", "status", "late", "eta")):
        return "status"
    return "open_question"


def handle(text: str) -> str:
    intent = classify(text)
    match = ORDER_ID.search(text.upper())
    if intent in ("status", "cancel") and not match:
        return f"[{intent}] ask user for the order number"
    if intent == "status":
        return f"[status] call get_order_status({match.group(1)}) -> template reply"
    if intent == "cancel":
        return f"[cancel] show confirm card for {match.group(1)} -> backend cancel"
    return "[open_question] send to the LLM (only this branch needs a model)"


for msg in ["Where is A1029?", "cancel my order", "Cancel A1029 please", "Ideas for a Diwali snack box?"]:
    print(f"{msg:<32} {handle(msg)}")

