from collections import Counter
from itertools import combinations

BASKETS = [  # synthetic baskets
    {"bread", "butter", "milk"}, {"bread", "butter", "jam"}, {"milk", "cornflakes", "bananas"},
    {"bread", "eggs", "milk"}, {"poha", "curd", "bananas"}, {"bread", "butter", "eggs"},
    {"milk", "bread"}, {"cornflakes", "milk"}, {"curd", "poha"}, {"milk", "tea"},
]

item_count = Counter(i for b in BASKETS for i in b)
pair_count = Counter(frozenset(p) for b in BASKETS for p in combinations(sorted(b), 2))


def popular(exclude, k=3):
    return [i for i, _ in item_count.most_common() if i not in exclude][:k]


def bought_with(item, k=3, min_pairs=2):
    """P(other | item) from co-occurrence, ignoring pairs seen fewer than min_pairs times."""
    scores = {}
    for pair, n in pair_count.items():
        if item in pair and n >= min_pairs:
            other = next(iter(pair - {item}))
            scores[other] = n / item_count[item]
    return sorted(scores, key=scores.get, reverse=True)[:k]


for item in ["bread", "poha", "tea"]:
    recs = bought_with(item) or popular({item})
    source = "co-purchase" if bought_with(item) else "popular fallback"
    print(f"{item:<6} -> {recs}  ({source})")
